// Generates replacement SVGs for images that are 404 on the original site, and rewrites the
// markdown links to point at them. Every image carries a visible "Generated by Claude" mark.
// Run: node scripts/gen-images.mjs
import fs from "node:fs";
import path from "node:path";

const OUT = path.resolve("public/assets/generated");
fs.mkdirSync(OUT, { recursive: true });
const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;");

const wrap = (title, body) => `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 450" font-family="Segoe UI, Arial, sans-serif">
<rect width="800" height="450" fill="#f8fafc"/>
${body}
<rect y="410" width="800" height="40" fill="#221551"/>
<text x="16" y="435" fill="#fff" font-size="14">Generated by Claude — illustration, not the original image</text>
<g transform="translate(640 10)"><rect width="150" height="26" rx="13" fill="#3b82f6"/><text x="75" y="18" fill="#fff" font-size="12" font-weight="700" text-anchor="middle">CLAUDE-GENERATED</text></g>
<text x="16" y="28" fill="#0f172a" font-size="16" font-weight="700">${esc(title)}</text>
</svg>`;

const box = (x, y, w, h, label, sub = "", fill = "#fff", stroke = "#334155") =>
  `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" fill="${fill}" stroke="${stroke}" stroke-width="2"/>
<text x="${x + w / 2}" y="${y + h / 2 - (sub ? 4 : -5)}" text-anchor="middle" font-size="15" font-weight="600" fill="#0f172a">${esc(label)}</text>` +
  (sub ? `<text x="${x + w / 2}" y="${y + h / 2 + 16}" text-anchor="middle" font-size="12" fill="#475569">${esc(sub)}</text>` : "");
const arrow = (x1, y1, x2, y2, both = false) =>
  `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#3b82f6" stroke-width="3" marker-end="url(#a)" ${both ? 'marker-start="url(#a)"' : ""}/>`;
const defs = `<defs><marker id="a" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#3b82f6"/></marker></defs>`;

const files = {};

files["bubble.svg"] = wrap("Bubble Algorithm — illustration", `
<rect y="260" width="800" height="150" fill="#bae6fd"/>
<path d="M0 270 Q50 245 100 270 T200 270 T300 270 T400 270 T500 270 T600 270 T700 270 T800 270 V300 H0z" fill="#7dd3fc"/>
<circle cx="400" cy="190" r="95" fill="#e0f2fe" stroke="#0ea5e9" stroke-width="5"/>
<ellipse cx="365" cy="150" rx="22" ry="12" fill="#fff" opacity=".8" transform="rotate(-30 365 150)"/>
<circle cx="370" cy="185" r="9" fill="#0f172a"/><circle cx="430" cy="185" r="9" fill="#0f172a"/>
<path d="M360 220 Q400 260 440 220" fill="none" stroke="#0f172a" stroke-width="6" stroke-linecap="round"/>
<circle cx="560" cy="160" r="26" fill="#e0f2fe" stroke="#0ea5e9" stroke-width="3"/>
<circle cx="600" cy="100" r="14" fill="#e0f2fe" stroke="#0ea5e9" stroke-width="3"/>
<circle cx="230" cy="130" r="20" fill="#e0f2fe" stroke="#0ea5e9" stroke-width="3"/>
<circle cx="190" cy="80" r="10" fill="#e0f2fe" stroke="#0ea5e9" stroke-width="3"/>
<text x="400" y="370" text-anchor="middle" font-size="18" fill="#0f172a">A bubble rising out of the water</text>`);

files["moon-programmers.svg"] = wrap("Committed to the Cause — illustration", `
<g fill="#fff"><circle cx="60" cy="70" r="2"/><circle cx="180" cy="40" r="2"/><circle cx="330" cy="90" r="2"/><circle cx="520" cy="50" r="2"/><circle cx="700" cy="110" r="2"/><circle cx="450" cy="130" r="2"/></g>
<rect width="800" height="410" fill="#0f172a"/>
<g fill="#fff"><circle cx="60" cy="70" r="2"/><circle cx="180" cy="50" r="2"/><circle cx="330" cy="100" r="2"/><circle cx="520" cy="60" r="2"/><circle cx="740" cy="120" r="2"/><circle cx="450" cy="140" r="2"/></g>
<circle cx="680" cy="110" r="48" fill="#3b82f6"/><path d="M650 100 q15 -20 30 0 q10 15 -10 25 q-20 0 -20 -25z" fill="#22c55e"/>
<ellipse cx="400" cy="470" rx="560" ry="150" fill="#cbd5e1"/>
<circle cx="130" cy="340" r="18" fill="#94a3b8"/><circle cx="660" cy="350" r="12" fill="#94a3b8"/>
${[230, 540].map((x) => `
<rect x="${x - 70}" y="270" width="140" height="8" fill="#475569"/>
<rect x="${x - 15}" y="278" width="10" height="55" fill="#475569"/><rect x="${x + 5}" y="278" width="10" height="55" fill="#475569"/>
<rect x="${x - 40}" y="215" width="80" height="55" rx="4" fill="#1e293b" stroke="#94a3b8" stroke-width="3"/>
<text x="${x}" y="249" text-anchor="middle" font-size="16" fill="#86efac" font-family="monospace">&lt;/&gt;</text>
<rect x="${x - 70}" y="285" width="40" height="55" rx="6" fill="#f59e0b" transform="translate(${x < 400 ? 20 : -20} 0)"/>
<circle cx="${x + (x < 400 ? -30 : 30)}" cy="240" r="0" />
<circle cx="${x + (x < 400 ? -62 : 62)}" cy="215" r="22" fill="#fde68a"/>
<rect x="${x + (x < 400 ? -90 : 40)}" y="235" width="56" height="64" rx="10" fill="#6366f1"/>
<circle cx="${x + (x < 400 ? -69 : 55)}" cy="210" r="3" fill="#0f172a"/><circle cx="${x + (x < 400 ? -55 : 69)}" cy="210" r="3" fill="#0f172a"/>
<path d="M${x + (x < 400 ? -70 : 54)} 222 q8 8 16 0" fill="none" stroke="#0f172a" stroke-width="2.5"/>`).join("")}
<text x="400" y="395" text-anchor="middle" font-size="16" fill="#0f172a">Two programmers, happily coding on the moon</text>`);

files["beckhoff-ce-hmi.svg"] = wrap("Beckhoff HMI on Windows CE — how the pieces fit", `${defs}
${box(300, 90, 200, 110, "Beckhoff CE panel", "Windows CE + runtime", "#ede9fe", "#6d28d9")}
${box(40, 60, 190, 70, "Editor / IDE", "from the SCADA provider")}
${box(40, 170, 190, 70, "SCADA licence", "ordered from the SCADA provider")}
${box(570, 90, 190, 110, "PLC / control", "Beckhoff TwinCAT or other", "#ecfdf5", "#16a34a")}
${arrow(230, 95, 300, 125)}${arrow(230, 205, 300, 175)}${arrow(500, 145, 570, 145, true)}
<text x="400" y="280" text-anchor="middle" font-size="15" fill="#0f172a">The panel ships with the runtime; design tools and the SCADA licence come from the SCADA vendor.</text>
<text x="400" y="305" text-anchor="middle" font-size="13" fill="#475569">Use a CE-based system with larger memory for the heavier SCADA applications.</text>`);

for (let n = 2; n <= 7; n++) {
  files[`intouch-opcua-${n}.svg`] = wrap(`Intouch as OPC UA server — step ${n - 1} (original screenshot unavailable)`, `${defs}
${box(40, 130, 200, 100, "OPC UA clients", "UaExpert · MES · other SCADA")}
${box(300, 110, 200, 140, "Intouch", "OPC UA server (2020 R2 SP1)", "#ede9fe", "#6d28d9")}
${box(560, 130, 200, 100, "Field devices", "PLCs · drives · I/O", "#ecfdf5", "#16a34a")}
${arrow(240, 180, 300, 180, true)}${arrow(500, 180, 560, 180, true)}
<text x="400" y="310" text-anchor="middle" font-size="15" fill="#0f172a">Intouch exposes its tags to OPC UA clients, enabling Industry 4.0 interconnectivity.</text>
<text x="400" y="340" text-anchor="middle" font-size="13" fill="#475569">The article's screenshot ${n - 1} of 6 is no longer available on the original site.</text>`);
}

files["modbus-mb-client.svg"] = wrap("Siemens MB_CLIENT ↔ Schneider PLC simulator (Modbus TCP)", `${defs}
${box(30, 70, 300, 250, "", "")}
<text x="180" y="100" text-anchor="middle" font-size="15" font-weight="700" fill="#0f172a">S7-1500 CPU 1511 · 192.168.1.100</text>
${box(55, 120, 250, 175, "MB_CLIENT", "", "#ede9fe", "#6d28d9")}
<g font-size="12" fill="#0f172a" font-family="monospace">
<text x="70" y="175">CONNECT : TCON_IP_v4</text><text x="85" y="195">ID = unique, not repeated</text>
<text x="85" y="213">ConnectionType = 11</text><text x="85" y="231">ActiveEstablished = 1</text>
<text x="85" y="249">ADDR = server IP</text><text x="85" y="267">RemotePort = 502</text></g>
${box(520, 120, 250, 175, "Schneider PLC", "PLC Simulator · Modbus TCP server", "#ecfdf5", "#16a34a")}
${arrow(330, 207, 520, 207, true)}
<text x="425" y="195" text-anchor="middle" font-size="13" fill="#475569">Modbus TCP</text>
<text x="400" y="365" text-anchor="middle" font-size="14" fill="#0f172a">Values read from the server land in the Instance DB array (first 10 records).</text>`);

for (const [name, svg] of Object.entries(files)) fs.writeFileSync(path.join(OUT, name), svg, "utf8");

// --- rewrite markdown links ---
const G = "./assets/generated/";
const map = [
  ["/blog/wp-content/uploads/2023/01/DALL·E-2023-01-03-13.37.08-bubble-smiling-coming-out-of-water-comic.-edited.png", "bubble.svg", "Claude-generated illustration: a smiling bubble rising out of water"],
  ["/blog/wp-content/uploads/2023/01/DALL·E-2023-01-03-10.39.21-Two-programmer-boys-sitting-at-their-computers-on-the-moon-programming-happily-comic-style..png", "moon-programmers.svg", "Claude-generated illustration: two programmers coding on the moon"],
  ["/user_images/Beckoff_CE_HMI.png", "beckhoff-ce-hmi.svg", "Claude-generated diagram: Beckhoff CE HMI components"],
  ...[2, 3, 4, 5, 6, 7].map((n) => [`/user_images/AvevaSystemPlatform_${n}.png`, `intouch-opcua-${n}.svg`, `Claude-generated diagram: Intouch OPC UA server (original screenshot ${n - 1} unavailable)`]),
  ["/user_images/SiemensModbusSchneider\\(1\\).png", "modbus-mb-client.svg", "Claude-generated diagram: MB_CLIENT connecting to a Schneider PLC simulator"],
];
let changed = 0;
const walk = (d) => fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)]));
for (const f of walk("src/content").filter((f) => f.endsWith(".mdx"))) {
  let t = fs.readFileSync(f, "utf8"), o = t;
  for (const [url, svg, alt] of map) t = t.replace(new RegExp(`!\\[[^\\]]*\\]\\(<?${url.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}>?\\)`, "g"), `![${alt}](${G}${svg})`);
  if (t !== o) { fs.writeFileSync(f, t, "utf8"); changed++; }
}
console.log(`wrote ${Object.keys(files).length} images, updated ${changed} pages`);
